/*
 * merkmale.js - features of a place as short German tags ("vegan", "rollstuhlgerecht", "draußen sitzen",
 * "Pizza") and its position for "In meiner Nähe". Offers window.Merkmale.  [V2] Added 2026-10-13.
 *
 * How it fits in:
 * - The data comes from js/data/merkmale.js (window.MERKMALE, made by tools/merkmale-holen.ps1 from
 *   OpenStreetMap). It is a separate file because js/data/orte.js is generated by another tool and must
 *   not be edited by hand. Key of both files: the id of the place ("n1209279102").
 * - Only what OpenStreetMap really says is shown. A place without tags simply shows none; "no" values
 *   (e.g. diet:vegan=no) are not shown either. There is no tag that is not in the data (for example no
 *   student discount: OpenStreetMap has no such information).
 * - Used by js/steckbrief.js (profile on the map), js/ortssuche.js (place search, also searchable:
 *   "vegan" finds every place with the tag) and js/standort.js (distances).
 * Classic script without modules, so the pages also work by double-click (file://).
 */
(function () {
    "use strict";

    // OpenStreetMap tag -> German word, for each value that is shown. Values not listed are not shown.
    var TAGS = [
        { key: "diet:vegan", values: { only: "rein vegan", yes: "vegan" } },
        { key: "diet:vegetarian", values: { only: "rein vegetarisch", yes: "vegetarisch" } },
        { key: "diet:halal", values: { only: "halal", yes: "halal" } },
        { key: "wheelchair", values: { yes: "rollstuhlgerecht", limited: "teilweise rollstuhlgerecht" } },
        { key: "outdoor_seating", values: { yes: "draußen sitzen", sidewalk: "draußen sitzen" } },
        { key: "internet_access", values: { wlan: "WLAN", yes: "WLAN" } },
        { key: "takeaway", values: { yes: "zum Mitnehmen", only: "nur zum Mitnehmen" } },
        { key: "delivery", values: { yes: "Lieferung" } },
        { key: "organic", values: { yes: "Bio", only: "Bio" } },
        { key: "second_hand", values: { yes: "Second Hand", only: "Second Hand" } }
    ];

    // Kitchen (OSM "cuisine", several values split by ";") in German. Unknown values are left out.
    var CUISINES = {
        afghan: "afghanisch", arab: "arabisch", asian: "asiatisch", bagel: "Bagels", breakfast: "Frühstück",
        bubble_tea: "Bubble Tea", burger: "Burger", cake: "Kuchen", caribbean: "karibisch", chicken: "Hähnchen",
        chinese: "chinesisch", ethiopian: "äthiopisch", fish: "Fisch", fish_and_chips: "Fish and Chips",
        friture: "Pommes", fries: "Pommes", fusion: "Fusion", german: "deutsch", greek: "griechisch",
        ice_cream: "Eis", indian: "indisch", italian: "italienisch", italian_pizza: "Pizza", japanese: "japanisch",
        juice: "Säfte", kebab: "Döner", korean: "koreanisch", mexican: "mexikanisch", moroccan: "marokkanisch",
        noodle: "Nudeln", pasta: "Pasta", persian: "persisch", pizza: "Pizza", poke: "Poke", ramen: "Ramen",
        regional: "regional", salad: "Salate", sandwich: "Sandwiches", savory_pancakes: "Pfannkuchen",
        seafood: "Meeresfrüchte", shawarma: "Shawarma", soup: "Suppen", spanish: "spanisch",
        steak_house: "Steakhaus", sushi: "Sushi", taiwanese: "taiwanisch", tea: "Tee", thai: "thailändisch",
        turkish: "türkisch", uyghur: "uigurisch", vietnamese: "vietnamesisch"
    };

    /** The data of one place from window.MERKMALE, or an empty object (file missing or place unknown). */
    function dataOf(place) {
        return (window.MERKMALE && window.MERKMALE[place.id]) || {};
    }

    /** Position of a place as { lat, lon }, or null. */
    function position(place) {
        var lage = dataOf(place).lage;
        return lage ? { lat: lage[0], lon: lage[1] } : null;
    }

    /** German words of the kitchen, without repeats: "pizza;italian_pizza" -> ["Pizza"]. */
    function cuisines(place) {
        var raw = dataOf(place).cuisine;
        var words = [];
        if (!raw) {
            return words;
        }
        var parts = raw.split(";");
        for (var i = 0; i < parts.length; i++) {
            var word = CUISINES[parts[i].trim().toLowerCase()];
            if (word && words.indexOf(word) < 0) {
                words.push(word);
            }
        }
        return words;
    }

    /** All tags of a place as German words: first the kitchen, then the features ("Pizza", "vegan", ...). */
    function tags(place) {
        var data = dataOf(place);
        var words = cuisines(place);
        for (var i = 0; i < TAGS.length; i++) {
            var word = TAGS[i].values[data[TAGS[i].key]];
            if (word && words.indexOf(word) < 0) {
                words.push(word);
            }
        }
        return words;
    }

    /**
     * Web address of a place, or null. Some entries have no "https://" in front ("www.example.de"),
     * those get it; anything that does not look like a web address is left out.
     */
    function website(place) {
        var url = dataOf(place).website;
        if (!url) {
            return null;
        }
        if (!/^https?:\/\//i.test(url)) {
            url = "https://" + url;
        }
        return /^https?:\/\/[^\s"'<>]+$/i.test(url) ? url : null;
    }

    /** Makes text safe for innerHTML (the web address comes from OpenStreetMap). */
    function escapeHtml(text) {
        return String(text)
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#39;");
    }

    /**
     * The feature the logged-in visitor chose under "Was dir wichtig ist" on konto.html (js/verlauf.js), e.g. "vegan",
     * or "" (added 2026-10-14).
     */
    function wish() {
        return window.Verlauf ? Verlauf.preferences().merkmal : "";
    }

    /** Does a tag fulfil the wish? "vegan" also counts "rein vegan". */
    function tagFits(word, wanted) {
        return wanted !== "" && (word === wanted || word === "rein " + wanted);
    }

    /**
     * Does a place have the feature the visitor finds important? Used by js/steckbrief.js and js/ortssuche.js to
     * put these places first (added 2026-10-14).
     */
    function matchesWish(place) {
        var wanted = wish();
        var words = tags(place);
        for (var i = 0; i < words.length; i++) {
            if (tagFits(words[i], wanted)) {
                return true;
            }
        }
        return false;
    }

    /**
     * HTML of the tags as a small list (css/style.css, part 21), or empty text if the place has none.
     * The tag that fulfils the visitor's wish gets the class place__tag--wish (a star and a stronger colour).
     */
    function markup(place) {
        var words = tags(place);
        if (words.length === 0) {
            return "";
        }
        var wanted = wish();
        var html = '<ul class="place__tags" aria-label="Merkmale laut OpenStreetMap">';
        for (var i = 0; i < words.length; i++) {
            var fits = tagFits(words[i], wanted);
            html += '<li class="place__tag' + (fits ? ' place__tag--wish' : '') + '">' + escapeHtml(words[i]) +
                (fits ? '<span class="visually-hidden"> (dir wichtig)</span>' : '') + '</li>';
        }
        return html + '</ul>';
    }

    /**
     * Link "Webseite" of a place (opens in a new tab), or empty text if OpenStreetMap has no web address.
     * className: the class of the link, so it looks like the link "Route" next to it.
     */
    function websiteMarkup(place, className) {
        var url = website(place);
        if (!url) {
            return "";
        }
        return '<a class="' + className + '" href="' + escapeHtml(url) + '" target="_blank" rel="noopener">Webseite' +
            '<span class="visually-hidden"> von ' + escapeHtml(place.name) + ' (öffnet in neuem Tab)</span></a>';
    }

    window.Merkmale = {
        tags: tags,            // ["Pizza", "vegan", ...]: also used for the search text in js/ortssuche.js
        markup: markup,
        matchesWish: matchesWish,  // places with the feature of "Was dir wichtig ist" come first (2026-10-14)
        websiteMarkup: websiteMarkup,
        position: position
    };
})();
